class Solution {
public:
    int minimumCoins(vector<int>& prices) {
        int n = prices.size();
        vector<int> dp(n + 2);
        deque<int> q;
        for (int i = n; i >= 1; --i) {
            while (!q.empty() && q.front() > min(n + 1, 2 * i + 1)) q.pop_front();
            while (!q.empty() && dp[q.back()] >= dp[i + 1]) q.pop_back();
            q.push_back(i + 1);
            dp[i] = prices[i - 1] + dp[q.front()];
        }
        return dp[1];
    }
};
